package com.fasterxml.jackson.core.io;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NumberInput.parseLong(String)
 * Aiming for maximum branch and line coverage.
 */
public class NumberInput_parseLong_TriageGen0Test {

    @Test
    public void testParseLong_ShortString_IntPath() {
        // length <= 9: triggers the (long) parseInt(str) path
        assertEquals(123L, NumberInput.parseLong("123"));
        assertEquals(0L, NumberInput.parseLong("0"));
        assertEquals(-123456789L, NumberInput.parseLong("-123456789"));
        assertEquals(2147483647L, NumberInput.parseLong("2147483647")); // Max Int
    }

    @Test
    public void testParseLong_LongString_LongPath() {
        // length > 9: triggers the Long.parseLong(str) path
        assertEquals(1000000000L, NumberInput.parseLong("1000000000")); // length 10
        assertEquals(9223372036854775807L, NumberInput.parseLong("9223372036854775807")); // Max Long
        assertEquals(-9223372036854775808L, NumberInput.parseLong("-9223372036854775808")); // Min Long
    }

    @Test(expected = NumberFormatException.class)
    public void testParseLong_InvalidFormat_Short() {
        // length <= 9, should throw via parseInt
        NumberInput.parseLong("abc");
    }

    @Test(expected = NumberFormatException.class)
    public void testParseLong_InvalidFormat_Long() {
        // length > 9, should throw via Long.parseLong
        NumberInput.parseLong("1234567890abc");
    }

    @Test(expected = NumberFormatException.class)
    public void testParseLong_OverflowInt_Short() {
        // This tests the boundary of the 'if (length <= 9)' logic.
        // If a string is length 9 but exceeds Integer.MAX_VALUE (not possible for 9 digits, 
        // but let's test the logic flow), it would trigger parseInt.
        // Note: "2147483648" is length 10, so it skips the if and goes to Long.parseLong.
        // To test the parseInt path specifically, we use a valid 9-digit integer.
        NumberInput.parseLong("999999999");
    }

    @Test(expected = NumberFormatException.class)
    public void testParseLong_OverflowLong() {
        // length > 9, exceeds Long.MAX_VALUE
        NumberInput.parseLong("9223372036854775808");
    }

    @Test(expected = NullPointerException.class)
    public void testParseLong_NullInput() {
        NumberInput.parseLong(null);
    }
}
